"use client";

import * as React from "react";
import { FileCodeIcon, FileTextIcon } from "@phosphor-icons/react";
import { cn } from "@/lib/utils";
import { parseToolArgs, CODE_EXTENSIONS, fileExtOf } from "./utils";
import type { ChatToolCall } from "../types";

type DiffRow = { type: "add" | "remove" | "context"; line: string };

// Line-level LCS diff. Bounded: falls back to a naive remove-then-add
// rendering when either side is too large for O(n*m) DP to stay fast.
function computeLineDiff(oldLines: string[], newLines: string[]): DiffRow[] {
  const n = oldLines.length;
  const m = newLines.length;
  if (n * m > 250000) {
    return [
      ...oldLines.map((line) => ({ type: "remove" as const, line })),
      ...newLines.map((line) => ({ type: "add" as const, line })),
    ];
  }

  const dp: number[][] = Array.from({ length: n + 1 }, () => new Array(m + 1).fill(0));
  for (let i = n - 1; i >= 0; i--) {
    for (let j = m - 1; j >= 0; j--) {
      dp[i][j] = oldLines[i] === newLines[j] ? dp[i + 1][j + 1] + 1 : Math.max(dp[i + 1][j], dp[i][j + 1]);
    }
  }

  const rows: DiffRow[] = [];
  let i = 0;
  let j = 0;
  while (i < n && j < m) {
    if (oldLines[i] === newLines[j]) {
      rows.push({ type: "context", line: oldLines[i] });
      i++;
      j++;
    } else if (dp[i + 1][j] >= dp[i][j + 1]) {
      rows.push({ type: "remove", line: oldLines[i] });
      i++;
    } else {
      rows.push({ type: "add", line: newLines[j] });
      j++;
    }
  }
  while (i < n) {
    rows.push({ type: "remove", line: oldLines[i] });
    i++;
  }
  while (j < m) {
    rows.push({ type: "add", line: newLines[j] });
    j++;
  }
  return rows;
}

// Unified diff: red (-) removed lines, green (+) added lines, dimmed context.
export function DiffView({
  oldContent = "",
  newContent = "",
  fileName,
  note,
}: {
  oldContent?: string;
  newContent?: string;
  fileName?: string;
  note?: string;
}) {
  const rows = React.useMemo(
    () => computeLineDiff(oldContent.split("\n"), newContent.split("\n")),
    [oldContent, newContent]
  );

  const added = rows.filter((row) => row.type === "add").length;
  const removed = rows.filter((row) => row.type === "remove").length;

  const isCode = fileName ? CODE_EXTENSIONS.includes(fileExtOf(fileName)) : false;
  const FileIcon = isCode ? FileCodeIcon : FileTextIcon;

  let oldNo = 1;
  let newNo = 1;

  return (
    <div className="flex flex-col rounded-none border border-border bg-card overflow-hidden">
      {fileName ? (
        <div className="flex items-center justify-between border-b border-border bg-muted/50 px-3 py-2">
          <div className="flex min-w-0 items-center gap-2">
            <FileIcon className="size-4 shrink-0 text-muted-foreground" />
            <span className="truncate text-xs font-semibold text-foreground font-mono">{fileName}</span>
          </div>
          <span className="shrink-0 text-[10px] font-bold tabular-nums">
            <span className="text-emerald-600 dark:text-emerald-400">+{added}</span>{" "}
            <span className="text-red-500 dark:text-red-400">-{removed}</span>
          </span>
        </div>
      ) : null}

      {note ? (
        <div className="border-b border-border bg-muted/40 px-3 py-1.5 text-[10px] font-semibold text-muted-foreground">
          {note}
        </div>
      ) : null}

      <div className="max-h-72 overflow-auto font-mono text-[11.5px] leading-5">
        {rows.map((row, index) => {
          const displayOldNo = row.type !== "add" ? oldNo++ : null;
          const displayNewNo = row.type !== "remove" ? newNo++ : null;
          return (
            <div
              key={index}
              className={cn(
                "flex",
                row.type === "add" && "bg-emerald-50 dark:bg-emerald-500/10",
                row.type === "remove" && "bg-red-50 dark:bg-red-500/10"
              )}
            >
              <span className="w-8 shrink-0 select-none border-r border-border px-1.5 text-right text-muted-foreground">
                {displayOldNo ?? ""}
              </span>
              <span className="w-8 shrink-0 select-none border-r border-border px-1.5 text-right text-muted-foreground">
                {displayNewNo ?? ""}
              </span>
              <span
                className={cn(
                  "w-4 shrink-0 select-none text-center font-bold",
                  row.type === "add" && "text-emerald-600 dark:text-emerald-400",
                  row.type === "remove" && "text-red-500 dark:text-red-400"
                )}
              >
                {row.type === "add" ? "+" : row.type === "remove" ? "-" : ""}
              </span>
              <span className="flex-1 whitespace-pre px-1.5 text-foreground">{row.line || " "}</span>
            </div>
          );
        })}
      </div>
    </div>
  );
}

// Line counts for the card row's "+19 -6" diffstat. Returns null when the
// args aren't parseable (yet) — the caller falls back to the generic panel
// instead of rendering an empty diff.
export function computeFileDiffStats(toolCall: ChatToolCall): { added: number; removed: number } | null {
  const args = parseToolArgs(toolCall.args) || {};
  const name = (toolCall.name || "").toLowerCase();

  if (name === "write_file") {
    if (typeof args.content !== "string") return null;
    return { added: (args.content as string).split("\n").length, removed: 0 };
  }

  if (name === "edit_file") {
    if (typeof args.old_string !== "string" && typeof args.new_string !== "string") return null;
    const rows = computeLineDiff(
      String(args.old_string ?? "").split("\n"),
      String(args.new_string ?? "").split("\n")
    );
    return {
      added: rows.filter((row) => row.type === "add").length,
      removed: rows.filter((row) => row.type === "remove").length,
    };
  }

  return null;
}

// Reads a write_file / edit_file tool's arguments and renders the DiffView.
// write_file has no prior content available client-side, so the entire body
// renders as additions; edit_file diffs old_string against new_string.
export function FileDiffCard({ toolCall }: { toolCall: ChatToolCall }) {
  const args = parseToolArgs(toolCall.args) || {};
  const nameLower = (toolCall.name || "").toLowerCase();
  const filePath = (args.file_path as string) || (args.filePath as string) || (args.path as string) || "";

  if (nameLower === "edit_file") {
    const oldContent = typeof args.old_string === "string" ? args.old_string : "";
    const newContent = typeof args.new_string === "string" ? args.new_string : "";
    return (
      <DiffView
        fileName={filePath}
        oldContent={oldContent}
        newContent={newContent}
        note={args.replace_all ? "Replacing all occurrences" : undefined}
      />
    );
  }

  const content = typeof args.content === "string" ? args.content : "";
  return <DiffView fileName={filePath} oldContent="" newContent={content} />;
}

"use client";

import * as React from "react";
import { FileCodeIcon, FileTextIcon, MagnifyingGlassIcon } from "@phosphor-icons/react";
import { parseToolArgs, CODE_EXTENSIONS, fileExtOf } from "./utils";
import type { ChatToolCall } from "../types";

export interface GrepMatch {
  file: string;
  line: number;
  content: string;
}

export function parseGrepResults(resultText: string | undefined): GrepMatch[] {
  if (!resultText) return [];

  try {
    const parsed = JSON.parse(resultText);
    const matches = Array.isArray(parsed) ? parsed : parsed?.matches || parsed?.results;
    if (Array.isArray(matches)) {
      return matches
        .map((m) => ({
          file: m.Filename || m.filename || m.file || m.path || "",
          line: m.LineNumber || m.lineNumber || m.line || 0,
          content: m.LineContent || m.lineContent || m.content || "",
        }))
        .filter((m) => m.file);
    }
  } catch {
    // fall through to plain-text parsing
  }

  const matches: GrepMatch[] = [];
  const lines = resultText.split("\n");
  let currentFile = "";

  for (const raw of lines) {
    const line = raw.trim();
    if (!line) continue;

    if (line.endsWith(":") && !/^\d+:/.test(line)) {
      currentFile = line.slice(0, -1).trim();
    } else if (currentFile) {
      const match = line.match(/^(\d+):(.*)$/);
      if (match) {
        matches.push({ file: currentFile, line: parseInt(match[1], 10), content: match[2] });
      } else {
        matches.push({ file: currentFile, line: 0, content: line });
      }
    }
  }

  if (matches.length === 0) {
    return lines
      .map((l) => l.trim())
      .filter((l) => l && (l.startsWith("/") || l.includes(".") || l.includes("\\")))
      .map((l) => ({ file: l, line: 0, content: "" }));
  }

  return matches;
}

function escapeRegex(value: string): string {
  return value.replace(/[/\-\\^$*+?.()|[\]{}]/g, "\\$&");
}

function highlightMatch(text: string, query: string) {
  if (!query) return text;
  try {
    const parts = text.split(new RegExp(`(${escapeRegex(query)})`, "gi"));
    return (
      <span>
        {parts.map((part, i) =>
          part.toLowerCase() === query.toLowerCase() ? (
            <mark key={i} className="bg-yellow-100 text-foreground rounded-[2px] px-0.5 font-semibold dark:bg-yellow-500/35">
              {part}
            </mark>
          ) : (
            part
          )
        )}
      </span>
    );
  } catch {
    return text;
  }
}

export function GrepResultsView({ toolCall }: { toolCall: ChatToolCall }) {
  const parsedInput = parseToolArgs(toolCall.args) || {};
  const query = (parsedInput.pattern as string) || (parsedInput.Query as string) || (parsedInput.query as string) || "";
  const path = (parsedInput.path as string) || (parsedInput.SearchPath as string) || (parsedInput.searchPath as string) || "/";
  const results = parseGrepResults(toolCall.result);
  const done = toolCall.status !== "running";

  const fileGroups: Record<string, GrepMatch[]> = {};
  for (const match of results) {
    (fileGroups[match.file] ??= []).push(match);
  }
  const groupEntries = Object.entries(fileGroups);

  return (
    <div className="flex flex-col gap-3">
      <div className="flex flex-wrap items-center gap-1.5 text-xs">
        <span className="text-muted-foreground font-semibold uppercase tracking-wider">Grep:</span>
        <span className="inline-flex items-center gap-1 bg-blue-50 px-2 py-0.5 font-bold text-blue-700 dark:bg-blue-950 dark:text-blue-400">
          <MagnifyingGlassIcon className="size-3" />
          &quot;{query}&quot;
        </span>
        <span className="text-muted-foreground">in</span>
        <span className="inline-flex items-center gap-1 bg-muted px-2 py-0.5 font-semibold text-foreground">{path}</span>
      </div>

      {!done ? (
        <div className="flex flex-col gap-1.5">
          <div className="text-[10px] font-bold text-muted-foreground uppercase tracking-wider">Searching…</div>
          <div className="h-8 bg-muted animate-pulse" />
        </div>
      ) : groupEntries.length > 0 ? (
        <div className="max-h-60 overflow-auto flex flex-col gap-2.5">
          {groupEntries.map(([filePath, matches]) => {
            const fileName = filePath.split("/").pop() || filePath;
            const isCode = CODE_EXTENSIONS.includes(fileExtOf(fileName));
            const FileIcon = isCode ? FileCodeIcon : FileTextIcon;

            return (
              <div key={filePath} className="border border-border bg-card overflow-hidden">
                <div className="flex items-center gap-2 border-b border-border bg-muted/50 px-2.5 py-1.5">
                  <FileIcon className="size-3.5 text-muted-foreground" />
                  <span className="text-xs font-semibold text-foreground font-mono">{filePath}</span>
                  <span className="ml-auto bg-muted px-1 py-0.5 text-[9px] font-bold text-muted-foreground">
                    {matches.length} {matches.length === 1 ? "match" : "matches"}
                  </span>
                </div>

                <div className="divide-y divide-border font-mono text-[11px] leading-relaxed">
                  {matches.map((match, i) => (
                    <div key={i} className="flex hover:bg-muted/50">
                      {match.line > 0 && (
                        <div className="w-9 shrink-0 select-none border-r border-border py-1.5 pr-2.5 text-right font-bold text-muted-foreground">
                          {match.line}
                        </div>
                      )}
                      <div className="flex-1 py-1.5 pl-3 pr-2 whitespace-pre-wrap break-all text-foreground">
                        {highlightMatch(match.content, query)}
                      </div>
                    </div>
                  ))}
                </div>
              </div>
            );
          })}
        </div>
      ) : (
        <div className="text-xs text-muted-foreground italic">No matches found.</div>
      )}
    </div>
  );
}

"use client";

import * as React from "react";
import { CaretRightIcon, CaretDownIcon } from "@phosphor-icons/react";
import { cn } from "@/lib/utils";

type JsonValue = string | number | boolean | null | undefined | JsonValue[] | { [key: string]: JsonValue };

function valueClass(value: JsonValue): string {
  if (value === null || value === undefined) return "text-muted-foreground italic";
  switch (typeof value) {
    case "string":
      return "text-orange-600 dark:text-orange-400";
    case "number":
      return "text-blue-600 dark:text-blue-400";
    case "boolean":
      return "text-violet-600 dark:text-violet-400";
    default:
      return "text-foreground";
  }
}

function formatPrimitive(value: JsonValue): string {
  if (value === null) return "null";
  if (value === undefined) return "undefined";
  if (typeof value === "string") return `"${value}"`;
  return String(value);
}

// One-line preview shown for a collapsed object/array, e.g. {type: "none"} or
// [1, 2, 3] - truncated so a huge nested value doesn't blow out the row.
function collapsedPreview(value: JsonValue): string {
  const isArray = Array.isArray(value);
  const entries = isArray ? (value as JsonValue[]) : Object.entries(value as object);
  const inner = isArray
    ? (entries as JsonValue[]).map((v) =>
        v !== null && typeof v === "object" ? (Array.isArray(v) ? "[…]" : "{…}") : formatPrimitive(v)
      )
    : (entries as [string, JsonValue][]).map(
        ([k, v]) => `${k}: ${v !== null && typeof v === "object" ? (Array.isArray(v) ? "[…]" : "{…}") : formatPrimitive(v)}`
      );
  const text = `${isArray ? "[" : "{"}${inner.join(", ")}${isArray ? "]" : "}"}`;
  return text.length > 80 ? `${text.slice(0, 77)}…` : text;
}

function JsonNode({ keyName, value, depth }: { keyName: string | number | null; value: JsonValue; depth: number }) {
  const isObject = value !== null && typeof value === "object";
  const isArray = isObject && Array.isArray(value);
  const isEmpty = isObject && (isArray ? (value as JsonValue[]).length === 0 : Object.keys(value as object).length === 0);
  // Top level (depth 0) starts expanded so the shape is visible at a glance;
  // nested objects/arrays start collapsed to keep the tree from opening fully.
  const [open, setOpen] = React.useState(depth === 0);

  if (!isObject || isEmpty) {
    return (
      <div className="flex gap-1.5 py-0.5 font-mono text-[11px] leading-relaxed">
        {keyName != null && <span className="shrink-0 font-semibold text-foreground">{keyName}:</span>}
        <span className={cn("break-all", isEmpty ? "text-muted-foreground" : valueClass(value))}>
          {isEmpty ? (isArray ? "[]" : "{}") : formatPrimitive(value)}
        </span>
      </div>
    );
  }

  const entries: [string | number, JsonValue][] = isArray
    ? (value as JsonValue[]).map((v, i) => [i, v])
    : Object.entries(value as object);

  return (
    <div className="font-mono text-[11px] leading-relaxed">
      <button
        type="button"
        onClick={() => setOpen((v) => !v)}
        className="flex w-full items-start gap-1 py-0.5 text-left hover:bg-muted"
      >
        {open ? (
          <CaretDownIcon className="size-3 mt-0.5 shrink-0 text-muted-foreground" />
        ) : (
          <CaretRightIcon className="size-3 mt-0.5 shrink-0 text-muted-foreground" />
        )}
        <span className="break-all">
          {keyName != null && <span className="font-semibold text-foreground">{keyName}: </span>}
          {open ? (
            <span className="text-muted-foreground">{isArray ? "[" : "{"}</span>
          ) : (
            <span className="text-muted-foreground">{collapsedPreview(value)}</span>
          )}
        </span>
      </button>

      {open && (
        <div className="ml-4 border-l border-border pl-2.5">
          {entries.map(([k, v]) => (
            <JsonNode key={k} keyName={isArray ? null : k} value={v} depth={depth + 1} />
          ))}
        </div>
      )}
      {open && <div className="text-muted-foreground">{isArray ? "]" : "}"}</div>}
    </div>
  );
}

/**
 * Collapsible, syntax-colored JSON tree. Top-level keys render expanded;
 * nested objects/arrays start collapsed with a one-line preview, expandable
 * via the caret - same shape as a typical API request/response inspector.
 */
export function JsonTreeView({ data, className }: { data: unknown; className?: string }) {
  if (data === null || typeof data !== "object") {
    return (
      <div className={cn("font-mono text-[11px]", valueClass(data as JsonValue), className)}>
        {formatPrimitive(data as JsonValue)}
      </div>
    );
  }

  const entries: [string | number, JsonValue][] = Array.isArray(data)
    ? data.map((v, i) => [i, v])
    : Object.entries(data as object);
  if (entries.length === 0) {
    return (
      <div className={cn("font-mono text-[11px] text-muted-foreground", className)}>
        {Array.isArray(data) ? "[]" : "{}"}
      </div>
    );
  }

  return (
    <div className={className}>
      {entries.map(([k, v]) => (
        <JsonNode key={k} keyName={Array.isArray(data) ? null : k} value={v} depth={0} />
      ))}
    </div>
  );
}

"use client";

import * as React from "react";
import {
  FileTextIcon,
  FileCodeIcon,
  FolderIcon,
  FolderOpenIcon,
  CaretRightIcon,
  CaretDownIcon,
} from "@phosphor-icons/react";
import { Button } from "@/components/ui/button";
import { Skeleton } from "@/components/ui/skeleton";
import { ScrollArea } from "@/components/ui/scroll-area";
import { Empty, EmptyHeader, EmptyMedia, EmptyTitle } from "@/components/ui/empty";
import { parseToolArgs, parseLsResults, buildLsTree, type LsTreeNode } from "./utils";
import type { ChatToolCall } from "../types";

// Same file-vs-code icon split file-explorer-editor.tsx uses, so a listed
// entry reads the same way whether you're looking at it in the Explorer
// sidebar or in an `ls` tool call's result.
function fileIcon(name: string) {
  const ext = name.split(".").pop()?.toLowerCase();
  if (ext === "md" || ext === "markdown" || ext === "txt") {
    return <FileTextIcon className="size-3.5 shrink-0 text-muted-foreground" />;
  }
  return <FileCodeIcon className="size-3.5 shrink-0 text-muted-foreground" />;
}

// One tree row, recursive — a directory node is its own caret+folder toggle
// (icon swaps open/closed) with its children indented underneath; a file
// node is a plain leaf row. Mirrors file-explorer-editor.tsx's per-folder
// expand/collapse instead of a single flat list.
function TreeRow({ node, depth, collapsed, onToggle }: {
  node: LsTreeNode;
  depth: number;
  collapsed: Set<string>;
  onToggle: (path: string) => void;
}) {
  const indent = { paddingLeft: `${8 + depth * 14}px` };

  if (!node.isDir) {
    return (
      <div
        style={indent}
        className="flex min-w-0 items-center gap-1.5 py-1 pr-2 text-xs text-muted-foreground hover:bg-muted/40 hover:text-foreground"
      >
        {fileIcon(node.name)}
        <span className="whitespace-nowrap font-mono">{node.name}</span>
      </div>
    );
  }

  // Open by default — a node is only closed once the user explicitly
  // collapses it, so a result that streams in after mount (or gains new
  // top-level entries) doesn't need its own "start expanded" bookkeeping.
  const isOpen = !collapsed.has(node.path);
  return (
    <div className="flex flex-col">
      <Button
        type="button"
        variant="ghost"
        style={indent}
        onClick={() => onToggle(node.path)}
        className="h-auto w-full min-w-0 justify-start gap-1 rounded-none py-1 pr-2 text-left text-xs font-normal text-muted-foreground"
      >
        {isOpen ? <CaretDownIcon className="size-3 shrink-0" /> : <CaretRightIcon className="size-3 shrink-0" />}
        {isOpen ? <FolderOpenIcon className="size-3.5 shrink-0" /> : <FolderIcon className="size-3.5 shrink-0" />}
        <span className="whitespace-nowrap font-mono">{node.name}</span>
      </Button>
      {isOpen &&
        node.children?.map((child) => (
          <TreeRow key={child.path} node={child} depth={depth + 1} collapsed={collapsed} onToggle={onToggle} />
        ))}
    </div>
  );
}

// Renders like file-explorer-editor.tsx's Explorer tree: a caret toggle for
// the listing itself, a folder icon that swaps open/closed, and — since an
// `ls` entry can carry slashes ("/memories/agent/") the flat listing never
// groups on its own — a real nested tree underneath where every directory
// is its own independently expandable node.
export function LsDirectoryCard({ toolCall }: { toolCall: ChatToolCall }) {
  const args = parseToolArgs(toolCall.args) || {};
  const path = (args.path as string) || (args.dir as string) || (args.directory as string) || "/";
  const items = parseLsResults(toolCall.result);
  const tree = React.useMemo(() => buildLsTree(items), [items]);
  const done = toolCall.status !== "running";
  // Starts expanded — this card only renders once the outer tool-call card
  // is already open, so a second click just to see the listing would be
  // redundant. The toggle exists for re-collapsing a long listing.
  const [open, setOpen] = React.useState(true);
  const [collapsedPaths, setCollapsedPaths] = React.useState<Set<string>>(() => new Set());

  const toggleNode = (nodePath: string) => {
    setCollapsedPaths((prev) => {
      const next = new Set(prev);
      if (next.has(nodePath)) next.delete(nodePath);
      else next.add(nodePath);
      return next;
    });
  };

  return (
    <div className="flex min-w-0 flex-col overflow-hidden border border-border">
      <Button
        type="button"
        variant="ghost"
        onClick={() => setOpen((v) => !v)}
        className="h-auto w-full min-w-0 justify-start gap-1.5 rounded-none bg-muted/10 px-2 py-1.5 text-left text-[11px] font-semibold uppercase tracking-wider text-muted-foreground"
      >
        {open ? <CaretDownIcon className="size-3 shrink-0" /> : <CaretRightIcon className="size-3 shrink-0" />}
        {open ? <FolderOpenIcon className="size-3.5 shrink-0" /> : <FolderIcon className="size-3.5 shrink-0" />}
        <span className="min-w-0 truncate font-mono normal-case">{path}</span>
      </Button>
      {open &&
        (!done ? (
          <div className="flex flex-col gap-1.5 p-2">
            <Skeleton className="h-5 w-3/4" />
            <Skeleton className="h-5 w-1/2" />
            <Skeleton className="h-5 w-2/3" />
          </div>
        ) : tree.length > 0 ? (
          // A folder tree can run both long (many siblings) and wide (deep
          // nesting pushes indentation out, long names) — rows use
          // whitespace-nowrap rather than truncating, so nothing is ever
          // silently clipped; min-w-0 (threaded down through every row) is
          // what stops that width from forcing this card wider than its
          // container instead of just scrolling within it.
          // orientation="both" gets a real horizontal scrollbar for the
          // wide case, alongside the existing vertical one for the long case.
          <ScrollArea orientation="both" className="max-h-56 min-w-0">
            <div className="flex min-w-0 flex-col py-1">
              {tree.map((node) => (
                <TreeRow key={node.path} node={node} depth={0} collapsed={collapsedPaths} onToggle={toggleNode} />
              ))}
            </div>
          </ScrollArea>
        ) : (
          <Empty className="p-4">
            <EmptyHeader>
              <EmptyMedia variant="icon">
                <FolderIcon />
              </EmptyMedia>
              <EmptyTitle className="text-xs">Empty directory</EmptyTitle>
            </EmptyHeader>
          </Empty>
        ))}
    </div>
  );
}

"use client";

import { FileCodeIcon, FileTextIcon } from "@phosphor-icons/react";
import { Spinner } from "@/components/ui/spinner";
import { getReadFileToolDetails, CODE_EXTENSIONS, fileExtOf } from "./utils";
import type { ChatToolCall } from "../types";

// Split file content into display lines + line numbers, stripping any
// "   1  content" prefixes the tool may have added.
function processLines(content: string, lineOffset: number) {
  if (!content) return { lines: [] as string[], lineNumbers: [] as number[] };
  const rawLines = content.split("\n");
  if (rawLines.length > 1 && rawLines[rawLines.length - 1] === "") {
    rawLines.pop();
  }

  let isPrefixed = true;
  const regex = /^\s*(\d+)(?:\s+(.*)|$)/;

  for (const line of rawLines) {
    if (line.trim() === "") continue;
    if (!regex.test(line)) {
      isPrefixed = false;
      break;
    }
  }

  if (isPrefixed && rawLines.length > 0) {
    const cleaned: string[] = [];
    const numbers: number[] = [];
    let lastNum = 0;

    for (const line of rawLines) {
      const match = line.match(regex);
      if (match) {
        cleaned.push(match[2] || "");
        lastNum = parseInt(match[1], 10);
        numbers.push(lastNum);
      } else {
        cleaned.push(line);
        lastNum += 1;
        numbers.push(lastNum);
      }
    }
    return { lines: cleaned, lineNumbers: numbers };
  }

  const offset = lineOffset || 0;
  const numbers = rawLines.map((_, i) => offset + i + 1);
  return { lines: rawLines, lineNumbers: numbers };
}

export function ReadFileCard({ toolCall }: { toolCall: ChatToolCall }) {
  const details = getReadFileToolDetails(toolCall.args, toolCall.result);
  const content = details?.content ?? "";
  const otherArgs = details?.otherArgs ?? {};
  const filePath = details?.filePath ?? "";
  const lineOffset = (otherArgs.offset as number) ?? (otherArgs.offsetLine as number) ?? 0;

  const { lines, lineNumbers } = processLines(content, lineOffset);

  if (!details) {
    return (
      <pre className="max-h-56 overflow-auto whitespace-pre-wrap break-words font-mono text-xs leading-5 text-foreground bg-muted p-2.5 rounded-none border border-border">
        {toolCall.result || "No result yet."}
      </pre>
    );
  }

  const fileName = filePath.split("/").pop() || filePath;
  const isCode = CODE_EXTENSIONS.includes(fileExtOf(fileName));
  const FileIcon = isCode ? FileCodeIcon : FileTextIcon;
  const done = toolCall.status !== "running";

  return (
    <div className="flex flex-col rounded-none border border-border bg-card overflow-hidden">
      <div className="flex items-center justify-between border-b border-border bg-muted/50 px-3 py-2">
        <div className="flex items-center gap-2 min-w-0">
          <FileIcon className="size-4 shrink-0 text-muted-foreground" />
          <span className="truncate text-xs font-semibold text-foreground font-mono">{filePath}</span>
        </div>
      </div>

      {!done ? (
        <div className="flex flex-col items-center justify-center py-8 text-center text-muted-foreground">
          <Spinner className="size-5 mb-2 text-primary" />
          <span className="text-[11px] font-bold uppercase tracking-wider">Reading file content…</span>
        </div>
      ) : content ? (
        <div className="relative max-h-72 overflow-auto bg-[#0D1117] font-mono text-[11.5px] text-[#C9D1D9]">
          <div className="flex min-w-full">
            <div className="w-10 shrink-0 select-none border-r border-[#30363D] bg-[#161B22]/50 py-3 text-right pr-3 text-[10px] font-bold text-[#8B949E]">
              {lineNumbers.map((num, i) => (
                <div key={i} className="h-5 leading-5">
                  {num}
                </div>
              ))}
            </div>
            <div className="flex-1 py-3 pl-3 pr-4 overflow-x-auto select-text">
              {lines.map((line, i) => (
                <pre key={i} className="h-5 leading-5 whitespace-pre font-mono text-[#E6EDF2]">
                  {line || " "}
                </pre>
              ))}
            </div>
          </div>
        </div>
      ) : (
        <div className="flex flex-col items-center justify-center py-8 text-center text-muted-foreground">
          <FileTextIcon className="size-7 mb-2" />
          <span className="text-[11px] font-bold uppercase tracking-wider">Empty file or no content</span>
        </div>
      )}

      {done && content && (
        <div className="flex items-center justify-between border-t border-border bg-muted/50 px-3 py-2 text-[10px] font-bold text-muted-foreground uppercase tracking-tight select-none">
          <div>
            Showing lines {lineNumbers[0]}-{lineNumbers[lineNumbers.length - 1]}
          </div>
          <div>{lines.length} lines</div>
        </div>
      )}
    </div>
  );
}

"use client";

import * as React from "react";
import { CopyIcon, CheckIcon } from "@phosphor-icons/react";
import { tryParseJson } from "./utils";
import { JsonTreeView } from "./json-tree-view";
import { cn } from "@/lib/utils";

/**
 * A labeled "Input" / "Result" panel: a collapsible JSON tree (falls back to
 * plain text for non-JSON results), with a copy-to-clipboard button. Renders
 * the full tree with no height cap - nodes collapse individually instead of
 * the whole panel scrolling.
 */
export function RequestResponsePanel({
  label,
  text,
  isError,
  className,
}: {
  label: string;
  text: string | undefined;
  isError?: boolean;
  className?: string;
}) {
  const [copied, setCopied] = React.useState(false);

  const parsed = tryParseJson(text);
  const isJson = parsed !== null && typeof parsed === "object";

  if (!text) return null;

  const handleCopy = async () => {
    try {
      await navigator.clipboard.writeText(isJson ? JSON.stringify(parsed, null, 2) : text);
      setCopied(true);
      setTimeout(() => setCopied(false), 1500);
    } catch {
      // clipboard access denied — nothing to surface, the button just won't flip
    }
  };

  return (
    <div>
      <div className="mb-1 flex items-center justify-between">
        <div className="text-xs font-semibold text-muted-foreground">{label}</div>
        <button
          type="button"
          onClick={handleCopy}
          className="flex items-center gap-1 text-[10px] font-semibold text-muted-foreground hover:text-foreground"
        >
          {copied ? <CheckIcon className="size-3" /> : <CopyIcon className="size-3" />}
          {copied ? "Copied" : "Copy"}
        </button>
      </div>
      <div
        className={cn(
          "max-h-40 overflow-auto rounded-none border p-2",
          isError ? "border-destructive/30 bg-destructive/10" : "border-border bg-muted",
          className
        )}
      >
        {isJson ? (
          <JsonTreeView data={parsed} />
        ) : (
          <div
            className={cn(
              "whitespace-pre-wrap break-words font-mono text-[11px] leading-relaxed",
              isError ? "text-destructive" : "text-foreground"
            )}
          >
            {text}
          </div>
        )}
      </div>
    </div>
  );
}

// Shared parsing helpers for the specialized tool-call renderers below.
// Ported from frontend/src/components/agents/agui/utils.js — trimmed to only
// what the platform's ToolCallCard dispatch needs.

export function tryParseJson(value: string | undefined | null): unknown {
  if (!value || typeof value !== "string") return null;
  try {
    return JSON.parse(value);
  } catch {
    return null;
  }
}

// Tool arguments can arrive double-encoded — LangChain's tool tracer wraps
// stringified args as { input: "<json>" }. Unwrap that envelope so callers
// see the real args (file_path, old_string, todos, ...). Safe on clean args.
export function parseToolArgs(argsText: string | undefined): Record<string, unknown> | null {
  const parsed = tryParseJson(argsText) as Record<string, unknown> | null;
  if (parsed && typeof parsed.input === "string" && Object.keys(parsed).length === 1) {
    return (tryParseJson(parsed.input) as Record<string, unknown> | null) ?? parsed;
  }
  return parsed;
}

const PATH_KEYS = [
  "file_path",
  "filePath",
  "path",
  "filename",
  "fileName",
  "targetFile",
  "TargetFile",
  "target_file",
];

function findPath(args: Record<string, unknown>): string {
  for (const key of PATH_KEYS) {
    if (typeof args[key] === "string") return args[key] as string;
  }
  return "";
}

export function isLsTool(name: string | undefined): boolean {
  if (!name) return false;
  const lower = name.toLowerCase();
  return (
    lower === "ls" ||
    lower === "list_dir" ||
    lower === "list_directory" ||
    lower.includes("list_dir") ||
    lower.includes("list_directory")
  );
}

export function isReadFileTool(name: string | undefined): boolean {
  if (!name) return false;
  const lower = name.toLowerCase();
  return (
    lower === "read_file" ||
    lower === "view_file" ||
    lower.includes("read_file") ||
    lower.includes("view_file")
  );
}

export function isFileWriteTool(name: string | undefined): boolean {
  return (name || "").toLowerCase() === "write_file";
}

export function isFileEditTool(name: string | undefined): boolean {
  return (name || "").toLowerCase() === "edit_file";
}

export function isGrepTool(name: string | undefined): boolean {
  return (name || "").toLowerCase().includes("grep");
}

export interface LsEntry {
  name: string;
  isDir: boolean;
}

export function parseLsResults(resultText: string | undefined): LsEntry[] {
  if (!resultText) return [];

  const parsed = tryParseJson(resultText);
  if (Array.isArray(parsed)) {
    return parsed.map((item) => {
      if (typeof item === "string") {
        const isDir = item.endsWith("/") || item.includes("(directory)");
        return { name: item.replace(/\(directory\)/g, "").trim(), isDir };
      }
      const obj = item as Record<string, unknown>;
      return {
        name: (obj.name as string) || (obj.path as string) || "",
        isDir: !!(obj.isDir || obj.is_dir || obj.isDirectory),
      };
    });
  }

  return resultText
    .split("\n")
    .map((line) => line.trim())
    .filter(Boolean)
    .map((line) => {
      const isDir =
        line.endsWith("/") ||
        line.toLowerCase().includes("(directory)") ||
        line.toLowerCase().includes("(dir)");
      const name = line.replace(/\(directory\)/gi, "").replace(/\(dir\)/gi, "").trim();
      return { name, isDir };
    });
}

export interface ReadFileDetails {
  filePath: string;
  content: string;
  otherArgs: Record<string, unknown>;
}

export function getReadFileToolDetails(args: string | undefined, result: string | undefined): ReadFileDetails | null {
  const parsedArgs = parseToolArgs(args) || {};
  const filePath = findPath(parsedArgs);
  if (!filePath) return null;

  const otherArgs: Record<string, unknown> = {};
  for (const [key, val] of Object.entries(parsedArgs)) {
    const isPathKey = PATH_KEYS.some((pk) => pk.toLowerCase() === key.toLowerCase());
    if (!isPathKey) otherArgs[key] = val;
  }

  return { filePath, content: result || "", otherArgs };
}

export interface LsTreeNode {
  name: string;
  path: string;
  isDir: boolean;
  children?: LsTreeNode[];
}

// An `ls` result is flat, but entries can still carry slashes (e.g.
// "/memories/agent/", "/memories/user/") that share a common parent the
// listing itself never names. Group those into a real nested tree — same
// technique as file-explorer-editor.tsx's buildFileTree — so shared
// prefixes collapse into one expandable "memories" node instead of two
// separate top-level rows that both start with "/memories/".
export function buildLsTree(items: LsEntry[]): LsTreeNode[] {
  interface MutableNode {
    name: string;
    path: string;
    isDir: boolean;
    children: Map<string, MutableNode>;
  }
  const root = new Map<string, MutableNode>();

  for (const item of items) {
    const parts = item.name.split("/").filter(Boolean);
    if (parts.length === 0) continue;
    let level = root;
    let currentPath = "";
    parts.forEach((part, i) => {
      currentPath = currentPath ? `${currentPath}/${part}` : part;
      const isLast = i === parts.length - 1;
      let node = level.get(part);
      if (!node) {
        node = { name: part, path: currentPath, isDir: isLast ? item.isDir : true, children: new Map() };
        level.set(part, node);
      } else if (isLast) {
        node.isDir = item.isDir;
      }
      level = node.children;
    });
  }

  function finalize(map: Map<string, MutableNode>): LsTreeNode[] {
    return Array.from(map.values())
      .sort((a, b) => {
        if (a.isDir !== b.isDir) return a.isDir ? -1 : 1;
        return a.name.localeCompare(b.name);
      })
      .map((n) => ({
        name: n.name,
        path: n.path,
        isDir: n.isDir,
        children: n.children.size ? finalize(n.children) : undefined,
      }));
  }

  return finalize(root);
}

// Common code file extensions, used to pick a "code" vs "text" file icon.
export const CODE_EXTENSIONS = [
  "js",
  "jsx",
  "ts",
  "tsx",
  "json",
  "html",
  "css",
  "py",
  "sh",
  "go",
  "rs",
  "md",
  "yaml",
  "yml",
];

export function fileExtOf(fileName: string): string {
  return fileName.includes(".") ? fileName.split(".").pop()!.toLowerCase() : "";
}

